class Solution {
    bool fits(const string& text, int w, int h, int size, FontInfo& fontInfo) {
        if (fontInfo.getHeight(size) > h) return false;
        long long totalW = 0;
        for (char ch : text) {
            totalW += fontInfo.getWidth(size, ch);
            if (totalW > w) return false;
        }
        return true;
    }
public:
    int maxFont(string text, int w, int h, vector<int>& fonts, FontInfo fontInfo) {
        int l = 0, r = fonts.size() - 1;
        int ans = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (fits(text, w, h, fonts[mid], fontInfo)) {
                ans = fonts[mid];
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        return ans;
    }
};

interface FontInfo {
    public int getWidth(int fontSize, char ch);
    public int getHeight(int fontSize);
}

class Solution {
    private boolean fits(String text, int w, int h, int size, FontInfo fontInfo) {
        if (fontInfo.getHeight(size) > h) return false;
        long totalW = 0;
        for (char ch : text.toCharArray()) {
            totalW += fontInfo.getWidth(size, ch);
            if (totalW > w) return false;
        }
        return true;
    }
    public int maxFont(String text, int w, int h, int[] fonts, FontInfo fontInfo) {
        int l = 0, r = fonts.length - 1;
        int ans = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (fits(text, w, h, fonts[mid], fontInfo)) {
                ans = fonts[mid];
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        return ans;
    }
}

var maxFont = function(text, w, h, fonts, fontInfo) {
    function fits(size) {
        if (fontInfo.getHeight(size) > h) return false;
        let totalW = 0;
        for (const ch of text) {
            totalW += fontInfo.getWidth(size, ch);
            if (totalW > w) return false;
        }
        return true;
    }
    let l = 0, r = fonts.length - 1;
    let ans = -1;
    while (l <= r) {
        const mid = Math.floor((l + r) / 2);
        if (fits(fonts[mid])) {
            ans = fonts[mid];
            l = mid + 1;
        } else {
            r = mid - 1;
        }
    }
    return ans;
};
